// The biggest cities of each country (generated by scripts/fetch-cities.ts into data/cities.json).
import raw from '../../data/cities.json'
import type { Lang } from '../i18n'

/** n = [English, German] name, at = [lon, lat], cap = capital. Biggest first. */
export interface City { n: [string, string]; at: [number, number]; cap?: 1 }

const CITIES = raw as unknown as Record<string, City[]>

export const citiesOf = (countryId: string): City[] => CITIES[countryId] ?? []
export const cityName = (c: City, lang: Lang) => c.n[lang === 'de' ? 1 : 0]
